-- Resources articles, copied from the website so they can be edited in the portal.
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('plc-scan-cycle', 'How a PLC thinks: the scan cycle', 'Automation', 4, 'A PLC runs the same four steps over and over. Knowing them explains most strange PLC behaviour.', '{"body": ["A programmable logic controller is an industrial computer built to run one control program continuously. It does not react the instant an input changes. Instead it works in a fixed rhythm called the scan cycle.", "## The four steps", "First the PLC reads every input and copies the values into memory, the input image. Second it runs your program from top to bottom using that frozen snapshot. Third it writes the results to the output image and updates the physical outputs. Last it handles housekeeping such as communications and diagnostics. Then it starts again.", "## Why this matters on site", "Outputs only change at the end of a scan, and the order of your logic matters because later rungs see the results of earlier ones. A pulse shorter than one scan can be missed completely, which is why fast counters and interrupt blocks exist. If the scan time creeps up, suspect heavy communications or an oversized program. Most CPUs include a watchdog that faults the controller if a scan takes far too long, which stops a stuck program from controlling the plant blindly.", "When you troubleshoot, remember that what you see online is the state at the end of the last scan, not a live wire."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: How a PLC thinks: the scan cycle"}', 1, 0);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('ladder-start-stop', 'Reading ladder logic: the motor start-stop rung', 'Automation', 4, 'The seal-in circuit is the first pattern every technician should read at a glance.', '{"body": ["Ladder logic (LAD) looks like an electrical schematic turned sideways. Power flows from the left rail to the right rail through contacts, and a coil on the right switches on when the path is complete.", "## The seal-in circuit", "Take a motor with a Start button and a Stop button. The Start contact is normally open and the Stop contact is normally closed. When you press Start, power reaches the motor coil. A second contact from the same coil sits in parallel with Start. Once the coil is on, that contact closes and keeps the rung energised even after you release Start. This is the seal-in, or latching, circuit.", "Pressing Stop opens the normally closed contact and breaks the path, so the coil drops out and the seal-in opens too.", "## Why Stop is normally closed", "If a Stop wire breaks, a normally closed circuit opens and the motor stops. If Stop were wired normally open, a broken wire would silently remove your ability to stop the machine. This fail-safe habit applies to emergency stops and many other safety inputs.", "Read every rung left to right asking one question: what must be true for this coil to turn on?"], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Reading ladder logic: the motor start-stop rung"}', 1, 1);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('s7-1200-vs-s7-1500', 'S7-1200 or S7-1500: which Siemens controller fits?', 'Automation', 4, 'Both use TIA Portal. The right choice depends on machine size, speed and the features you need.', '{"body": ["Siemens sells two main families for new work, the S7-1200 and the S7-1500. Both are programmed in the same engineering software, TIA Portal, and both support ladder (LAD), function block diagram (FBD) and structured text in the form of SCL.", "## S7-1200: compact and cost-effective", "The S7-1200 suits small to medium machines and simple plants. It has an integrated PROFINET port, can be expanded with signal modules, and keeps panel space and cost down. It has no display on the CPU, so diagnostics are done through the software or an HMI.", "## S7-1500: performance and capacity", "The S7-1500 is aimed at larger, faster and more demanding applications. It offers more performance and memory, a built-in display on the CPU for quick diagnostics, stronger security features, integrated trace, and better support for advanced motion control.", "## How to choose", "Count your I/O, think about scan speed, the number of drives and axes, the need for network security, and how much the plant is likely to grow. Choosing the smaller controller is fine for a simple machine. For a plant you expect to expand, the S7-1500 can save a costly replacement later. Always check the current catalogue for exact specifications before you order."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: S7-1200 or S7-1500: which Siemens controller fits?"}', 1, 2);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('scaling-4-20ma-tia-portal', 'How to scale a 4-20 mA signal in TIA Portal', 'Instrumentation', 5, 'Turn a raw analog value into real engineering units with NORM_X and SCALE_X.', '{"body": ["A transmitter sends a current between 4 and 20 mA. The analog input module converts that current into an integer, and your program must convert the integer into units such as bar or degrees.", "## What the module gives you", "For a standard 4-20 mA input on a Siemens module, 4 mA reads as 0 and 20 mA reads as 27648. 12 mA is exactly halfway at 13824. A reading below 0 means the current has fallen under 4 mA, which is a useful sign of a fault.", "## Two instructions", "NORM_X turns the raw integer into a number between 0.0 and 1.0. Set MIN to 0 and MAX to 27648. SCALE_X then maps 0.0 to 1.0 onto your real range. For a pressure transmitter ranged 0 to 10 bar, set MIN to 0.0 and MAX to 10.0. At 12 mA the result is 5.0 bar.", "The result must go into a REAL tag. You can also do it with one line of SCL: engineering value equals raw divided by 27648 multiplied by the span, plus the low value.", "## Checks before you trust it", "Match the PLC range to the transmitter range exactly. Simulate the loop with a calibrator at 4, 12 and 20 mA and confirm the screen reads 0, 50 and 100 percent. Add alarm logic for readings below 3.6 mA or above 21 mA so that a broken wire cannot look like a real measurement."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: How to scale a 4-20 mA signal in TIA Portal"}', 1, 3);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('why-4-20-ma', 'Why industry uses 4-20 mA loops', 'Instrumentation', 4, 'A live zero, loop power and noise immunity make the current loop a durable standard.', '{"body": ["Most field transmitters still talk to controllers using a current between 4 and 20 mA. The reasons are practical, and they explain how to troubleshoot these loops.", "## A live zero", "Zero percent is 4 mA, not 0 mA. If the loop is broken, the current falls to 0 mA, which is clearly outside the normal range. A system that used 0 mA as zero could not tell a dead wire from a true minimum reading.", "## Current is robust", "In a series loop, the same current flows through every device. Wire resistance and electrical noise change the voltage but not the current, so the signal travels long distances through a noisy plant with little loss of accuracy.", "## Power and signal on two wires", "A two-wire transmitter takes its power from the loop itself, using the 4 mA that is always flowing. A typical loop has a 24 V DC supply, the transmitter, and an input resistor of around 250 ohms in the PLC. That resistor converts 4 to 20 mA into 1 to 5 V.", "## Faults to look for", "Industry guidance such as NAMUR NE43 treats readings below about 3.6 mA or above 21 mA as faults. When a loop misbehaves, put a multimeter in series, check the supply voltage at the transmitter terminals, then look for water in junction boxes and loose terminals."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Why industry uses 4-20 mA loops"}', 1, 4);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('pid-control-explained', 'PID control explained without the maths', 'Automation', 5, 'Proportional, integral and derivative: what each term does and when to use it.', '{"body": ["A PID controller holds a process value, such as a temperature or a flow, at a setpoint. It looks at the error, the difference between where you are and where you want to be, and decides how hard to push the output.", "## The three terms", "Proportional reacts to the present error. A bigger error gives a bigger push. On its own it usually leaves a small permanent offset. Integral adds up past error over time and keeps pushing until the offset disappears. Derivative reacts to how fast the error is changing, which can calm the response, but it also amplifies noise.", "## Which terms to use", "Most loops run well as PI. Flow and pressure loops are typically fast and noisy, so derivative is left off. Temperature loops are slow and often benefit from a little derivative. Some level loops use proportional only so that the tank is allowed to float between limits.", "## Problems to know", "Integral windup happens when the output is stuck at its limit while the integral keeps growing, so the loop overshoots badly afterwards. Good controllers include anti-windup. Also avoid tuning on a noisy signal without a filter.", "Modern PLCs include ready-made blocks such as PID_Compact in TIA Portal. They give you the structure, and you provide the understanding."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: PID control explained without the maths"}', 1, 5);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('tuning-a-pid-loop', 'Tuning a PID loop: a practical approach', 'Automation', 5, 'A safe, step-by-step way to improve a loop, plus the classic Ziegler-Nichols rules.', '{"body": ["A badly tuned loop wastes energy, wears valves and produces unstable product. Tuning is the art of choosing gain, integral time and derivative time so the loop is quick without being wild.", "## Start safely", "Agree the changes with operations, know the safe limits of the process, and record the current settings. Put the loop in manual first and make small output changes to learn how the process responds, including how long it takes to react.", "## Ziegler-Nichols closed-loop method", "Turn integral and derivative off. Raise proportional gain until the loop oscillates steadily. Call that gain Ku and the oscillation period Pu. A PI controller then starts at Kp equal to 0.45 Ku and Ti equal to Pu divided by 1.2. A PID controller starts at Kp equal to 0.6 Ku, Ti equal to Pu divided by 2 and Td equal to Pu divided by 8.", "This method pushes the process close to instability, so it is often not suitable on live plant. It also gives an aggressive result that needs softening.", "## Better habits", "Use auto-tune tools where they exist, such as the pre-tuning and fine-tuning in PID_Compact. Change one term at a time. Watch a trend, not just the screen value. Wait for the loop to settle after each change and write down every change you make."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Tuning a PID loop: a practical approach"}', 1, 6);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('three-phase-power-basics', 'Three-phase power basics', 'Electrical', 4, 'Why industry runs on three phases, and the one formula to remember.', '{"body": ["Three-phase power uses three alternating voltages of the same size, each offset by one third of a cycle, or 120 degrees. Almost every motor and large load in industry runs from it.", "## Why three phases", "A single-phase supply delivers power in pulses. Three phases together deliver a steady flow of power, so motors run smoothly and are smaller for the same rating. Three-phase windings also create a rotating magnetic field naturally, which is why simple induction motors can start without extra parts.", "## Voltages", "Line voltage is the voltage between two phases. Phase voltage is between one phase and neutral. Line voltage is the square root of three, about 1.73, times phase voltage. Australia is nominally 230 V phase and 400 V line at 50 Hz. Zimbabwe uses 50 Hz with a nominal 220 V phase and 380 V line. Always read the nameplate and the site voltage.", "## Power", "Real power in a balanced load is root three, multiplied by line voltage, line current and power factor. Unbalanced phases cause extra heating in motors, so a quick check of phase currents is a good habit.", "Swapping any two phases reverses the rotation of an induction motor. That is useful for reversing starters, and a hazard when reconnecting a pump, so always check rotation before coupling."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Three-phase power basics"}', 1, 7);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('motor-starting-methods', 'Starting motors: DOL, star-delta, soft starter or VSD?', 'Electrical', 5, 'Each starting method trades cost, torque and inrush current differently.', '{"body": ["When an induction motor starts, it draws far more current than it does at full speed. Choosing a starting method is a decision about how to manage that inrush.", "## Direct on line", "The simplest method connects the motor straight to the supply. It is cheap and reliable, but starting current is typically 5 to 8 times full-load current. That is fine for small motors and strong supplies, but can cause voltage dips on weak networks.", "## Star-delta", "The windings start in star, which cuts the starting current and torque to about one third, then switch to delta once the motor is up to speed. The switch-over can create a short current spike, and the low starting torque is a limit for heavy loads.", "## Soft starters", "Thyristors ramp the voltage up smoothly, reducing mechanical shock to belts, couplings and pipelines. They are good for pumps and conveyors, but do not give speed control.", "## Variable speed drives", "A VSD controls frequency and voltage. It starts the motor with low current and high torque, and lets you run at any speed. It costs more, but on pumps and fans it can save a large amount of energy.", "Match the method to the load torque, the supply strength, the cost and how often the motor starts."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Starting motors: DOL, star-delta, soft starter or VSD?"}', 1, 8);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('how-a-vsd-works', 'How a variable speed drive works', 'Electrical', 5, 'Rectify, smooth, then invert: what is happening inside the cabinet.', '{"body": ["A variable speed drive, also called a VSD or VFD, changes the speed of an AC motor by changing the frequency and voltage it supplies.", "## Three stages", "A rectifier converts the incoming AC to DC. A DC bus with capacitors smooths that DC. An inverter built from IGBT transistors switches the DC rapidly in a pattern called pulse-width modulation, creating an AC output of the frequency and voltage the control board asks for.", "## Setting up a drive", "Enter the motor nameplate data first: voltage, current, frequency, speed and power. Then set the ramp times, minimum and maximum frequency, and how the drive receives its speed command, for example 4-20 mA or a network. Run an auto-tune or motor identification if the drive offers one.", "## Energy saving", "For centrifugal pumps and fans, power drops roughly with the cube of speed. Running at 80 percent speed uses about half the power. That is why VSDs often pay for themselves quickly on mine water pumping.", "## Practical cautions", "Drives create electrical noise and harmonics. Use screened motor cable, keep it as short as practical, and follow the manufacturer''s earthing instructions. Long cables may need output filters to protect motor insulation. Capacitors hold dangerous charge after power is removed, so wait the stated time and prove the terminals dead before touching them."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: How a variable speed drive works"}', 1, 9);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('motor-protection', 'Protecting motors: overloads, short circuits and earth faults', 'Electrical', 4, 'Different faults need different protective devices, working together.', '{"body": ["A motor can be damaged by sustained overcurrent, a short circuit, an earth fault, a lost phase or overheating. No single device covers all of these, so a starter uses a combination.", "## Short-circuit protection", "Fuses and circuit breakers clear very high fault currents within milliseconds. They are sized to protect the cable and the starter, not the motor from slow overload.", "## Overload protection", "A thermal or electronic overload relay measures current and trips on an inverse time curve: a small overload is tolerated for a while, a large one trips quickly. Set it to the motor''s full-load current from the nameplate. A trip class, such as 10 or 20, states how quickly the relay trips at a high multiple of its setting. Heavy-starting loads may need a slower class.", "## Other protections", "Earth fault protection detects current leaking to the frame. Phase failure and unbalance protection stops single-phasing, a common cause of burnt windings. PTC thermistors or Pt100 sensors in the windings read actual temperature, which is the most direct protection.", "## When a motor trips", "Do not simply reset. Look for the cause: a jammed load, a bad bearing, a blocked cooling path, a loose connection or low voltage. Measure currents and insulation resistance, and fix what caused the trip."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Protecting motors: overloads, short circuits and earth faults"}', 1, 10);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('motor-control-centres', 'Motor control centres (MCCs) explained', 'Electrical', 4, 'How plants group starters, and what to check when you maintain one.', '{"body": ["A motor control centre is a line-up of metal cubicles that holds the starters for many motors in one place. It is the backbone of most processing plants.", "## How it is built", "A horizontal busbar feeds a vertical busbar in each section. Plug-in or withdrawable buckets each contain the parts for one motor: a breaker or fuse switch, a contactor, an overload relay or electronic protection unit, a control transformer and pilot devices. A faulty starter can be swapped quickly, often with a spare bucket.", "## Separation and safety", "IEC 61439 describes forms of internal separation that limit access to live parts and reduce the spread of a fault. Arc-fault containment and remote operation reduce the risk to the person at the switch.", "## Intelligent MCCs", "Many modern MCCs connect each starter to a PLC through PROFIBUS, PROFINET or EtherNet/IP. Operators see motor current, status and fault data without opening a door.", "## Maintenance", "Schedule thermographic scans under load to find hot connections, check busbar torque as the manufacturer specifies, clean and inspect contacts, keep drawings current, and label every bucket clearly. Never work on live equipment unless the task is permitted and the right controls are in place."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Motor control centres (MCCs) explained"}', 1, 11);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('hv-isolation-awareness', 'High voltage isolation: the principles behind safe switching', 'Safety', 5, 'An awareness article on the ideas behind safe HV work. It is not a procedure.', '{"body": ["High voltage, generally above 1000 V AC, can kill without contact because it can arc across a gap. Work on or near it is limited to authorised, trained and competent people following the site''s own written procedures.", "## The core ideas", "Safe work on HV equipment depends on a small number of ideas that apply everywhere. The circuit is planned and a switching program is agreed. It is isolated at every point of supply. The equipment is proven dead with a tester that has itself been proven. It is earthed so it cannot become live again. Isolation points are locked and tagged, and a permit controls who may work and where.", "## Dead, proven, earthed", "Isolated is not the same as dead, and dead is not the same as safe. Backfeed from another source, induced voltage and stored energy can all appear after an isolator is opened. That is why testing and earthing come before anyone touches anything.", "## Restoring supply", "Return to service follows its own checks: all persons clear, earths removed, tags and locks returned, permits closed, and the switching steps carried out in the agreed order and communicated clearly.", "## Training matters", "Tickets such as HV switching authorisations exist because the consequences of an error are severe. This article is general education only. Always follow your employer''s procedures, the applicable regulations and the instructions of the person in control of the installation."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: High voltage isolation: the principles behind safe switching"}', 1, 12);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('reading-single-line-diagrams', 'How to read a single-line diagram', 'Electrical', 4, 'Follow the power from source to load and every plant drawing becomes clearer.', '{"body": ["A single-line diagram, or one-line diagram, shows a three-phase electrical system using a single line for all three conductors. It is the map of a switchboard, substation or plant.", "## Start at the source", "Find the incoming supply, usually at the top or left. Follow the line downward through breakers, transformers, busbars and feeders until you reach the loads. At each device ask what it is, what it is rated for, and what it protects.", "## Symbols and ratings", "Learn the common symbols: circuit breaker, isolator, fuse, transformer, current transformer, voltage transformer, motor, and earth. Notes beside each symbol give ratings such as voltage, current, fault level and trip settings. Transformer labels give the voltage ratio and the winding connection, for example Dyn11.", "## Protection and metering", "Current and voltage transformers feed protection relays and meters. Relay symbols tell you which functions are fitted, such as overcurrent or earth fault. Note interlocks and normal switching positions.", "## Trust, but verify", "Drawings can be out of date. Check that the diagram matches the as-installed equipment and its revision date before you plan any switching or modification. Mark up differences and report them so the drawing set stays correct."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: How to read a single-line diagram"}', 1, 13);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('earthing-and-bonding', 'Earthing and bonding basics', 'Safety', 4, 'Why a low-resistance path to earth keeps people safe and makes protection trip.', '{"body": ["Earthing connects the exposed metal parts of equipment to the earth and back to the source. Its job is to make sure that a fault is cleared quickly and that dangerous voltages do not appear on things people can touch.", "## How a fault is cleared", "If a live conductor touches a metal frame, current flows through the protective earth conductor back to the supply. A low-impedance path lets that current rise high enough to trip a breaker or fuse in a short time. A high-impedance path might leave the frame live while the protection never operates.", "## Bonding", "Equipotential bonding connects metal parts together, such as structures, pipes and cable trays, so that they sit at about the same voltage. Then a person touching two parts at once sees little voltage between them.", "## RCDs", "A residual current device measures the difference between outgoing and returning current. If current is leaking through a person or the earth, it trips quickly. A 30 mA RCD is common for personal protection.", "## Testing", "Check earth continuity, measure earth-fault loop impedance where required, and inspect the earthing system regularly. Corroded or loose connections are the most common fault. In substations, designers also consider touch and step voltages around the earth grid."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Earthing and bonding basics"}', 1, 14);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('hazardous-areas-eeha', 'Hazardous areas and EEHA: zones and protection types', 'Safety', 5, 'Where explosive atmospheres can form, equipment must be chosen, installed and inspected differently.', '{"body": ["A hazardous area is a place where flammable gas, vapour or dust may be present in amounts that could cause an explosion. Fuel storage, some process plants and some mining areas include such zones. EEHA stands for Electrical Equipment in Hazardous Areas.", "## Zones", "For gases, Zone 0 has an explosive atmosphere continuously or for long periods. Zone 1 is where it is likely in normal operation. Zone 2 is where it is not likely, and if it occurs it lasts only a short time. Dust areas use Zones 20, 21 and 22 in the same way.", "## Protection types", "Ex d, flameproof, contains an internal explosion and cools the escaping gases. Ex e, increased safety, avoids sparks and hot surfaces. Ex i, intrinsic safety, limits the energy in a circuit so it cannot ignite the atmosphere. Ex p uses pressurisation with clean air or inert gas. Ex n is used in Zone 2.", "## Standards and competence", "The IEC 60079 series sets out the principles, and Australia applies it through the AS/NZS 60079 standards. Work on this equipment requires specific competence and records for each installation. Inspection levels range from visual to close to detailed.", "Never substitute a part or open an enclosure in a hazardous area without checking the certification and permits. A cable gland of the wrong type can invalidate an entire installation."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Hazardous areas and EEHA: zones and protection types"}', 1, 15);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('pressure-measurement', 'Pressure measurement and transmitters', 'Instrumentation', 4, 'Gauge, absolute and differential pressure, and how a transmitter turns force into a signal.', '{"body": ["Pressure is force per unit area. Industry uses kilopascals, bar and psi: one bar is 100 kPa, or about 14.5 psi.", "## Types of pressure", "Gauge pressure is measured against the atmosphere. Absolute pressure is measured against a perfect vacuum. Differential pressure, or DP, is the difference between two points, and is used for flow and level measurement.", "## How a transmitter works", "A diaphragm flexes under pressure. A capacitive or strain-gauge sensor turns that movement into an electrical change. Electronics linearise the signal and output 4-20 mA, often with HART communication on top for configuration and diagnostics.", "## Installing for good results", "Mount the transmitter so that process fluid cannot clog the impulse lines, and fit isolation and equalising valves so it can be zeroed and removed safely. For steam, use a condensate pot or loop so the sensor sees water, not live steam. Protect it from vibration and extreme temperature.", "## Setup and checking", "Set the lower and upper range values to match the process. Perform a zero trim with the transmitter vented. Check the 4-20 mA output at several points with a pressure calibrator, and record the result."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Pressure measurement and transmitters"}', 1, 16);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('flow-measurement', 'Choosing a flow meter', 'Instrumentation', 5, 'Orifice, magnetic, Coriolis, vortex and ultrasonic meters suit different fluids and budgets.', '{"body": ["Flow is the volume or mass of fluid passing a point each second or hour. There is no single best meter, so the choice depends on the fluid, the accuracy needed and the cost.", "## Differential pressure", "An orifice plate or venturi narrows the flow and creates a pressure drop. Flow is proportional to the square root of the differential pressure. These are simple and well proven, but cause a permanent pressure loss and need straight pipe runs.", "## Magnetic flowmeters", "These apply Faraday''s law and have no moving parts. They suit conductive liquids such as water, slurries and many chemicals. They do not work on non-conductive fluids such as oils or gases.", "## Coriolis", "A Coriolis meter measures mass flow directly and also reports density. It is highly accurate and can handle many fluids, but is the most expensive option.", "## Vortex and ultrasonic", "Vortex meters suit steam, gas and clean liquids. Ultrasonic meters can be clamped on the outside of a pipe, which is useful for checking flow without shutting down.", "## Installation", "Keep the pipe full for liquid meters, give the recommended straight run before and after the meter, and ground magnetic meters correctly. Poor installation causes more flow errors than the meter itself."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Choosing a flow meter"}', 1, 17);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('level-measurement', 'Measuring level in tanks and silos', 'Instrumentation', 4, 'Radar, pressure, float and fork switches: matching the method to the material.', '{"body": ["Level tells you how much a tank or bin holds, protects pumps from running dry, and prevents overflows. The best technology depends on the material and the conditions inside the vessel.", "## Hydrostatic pressure", "A pressure or DP transmitter at the bottom of the tank reads the weight of the liquid above it. Pressure equals density times gravity times height, so level can be calculated if the density is known. It is simple and robust for clean liquids.", "## Radar", "Non-contact radar sends microwaves to the surface and measures the echo. It is largely unaffected by temperature, pressure and vapour, so it works in many harsh applications. Guided wave radar sends the pulse down a probe.", "## Ultrasonic, float and switches", "Ultrasonic sensors are economical for open tanks and sumps, but foam, steam and dust can disturb them. Float switches give simple high and low alarms. Vibrating fork switches detect the presence of liquid or powder at a single point.", "## Common issues", "Foam, turbulence, build-up on probes, changing density and obstacles inside the vessel such as agitators can all confuse a sensor. Check the installation drawing, set the empty and full distances carefully, and compare the reading with a physical dip when commissioning."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Measuring level in tanks and silos"}', 1, 18);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('temperature-rtd-vs-thermocouple', 'Temperature sensors: RTD or thermocouple?', 'Instrumentation', 4, 'Pt100 sensors are accurate and stable. Thermocouples are rugged and reach higher temperatures.', '{"body": ["The two main industrial temperature sensors work on different principles, and each has a place.", "## RTD (Pt100)", "A resistance temperature detector uses a platinum element whose resistance rises with temperature. A Pt100 reads 100 ohms at 0 degrees Celsius and about 138.5 ohms at 100 degrees. It is accurate, stable and has a nearly linear response, and is common up to several hundred degrees. Three-wire connection compensates for the resistance of the cable, and four-wire is used for the best accuracy.", "## Thermocouples", "A thermocouple joins two dissimilar metals. The junction produces a small voltage that depends on the temperature difference between the hot and cold ends. Type K is the common general-purpose choice and, for example, produces about 4.1 mV at 100 degrees Celsius with the cold end at 0 degrees. Thermocouples respond quickly, are rugged, and measure well over 1000 degrees.", "## Practical points", "The input card must compensate for the cold junction, and you must use the correct thermocouple extension cable and polarity. Using ordinary copper wire adds extra junctions and false readings. For most process work below about 500 degrees, an RTD is the better choice for accuracy. For furnaces and kilns, thermocouples are usually the answer."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Temperature sensors: RTD or thermocouple?"}', 1, 19);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('control-valves-and-positioners', 'Control valves and positioners', 'Instrumentation', 5, 'The final control element: how a valve turns a 4-20 mA signal into flow.', '{"body": ["A control valve is the part of the loop that actually changes the process. A controller can only be as good as the valve it moves.", "## The parts", "A valve has a body and trim that restrict the flow, an actuator that moves the stem, and usually a positioner. The positioner compares the 4-20 mA command with the real stem position and adjusts air to the actuator until they match. It corrects friction and keeps the valve accurate.", "## Fail position", "Decide what the valve should do if air or signal is lost. Fail-open, fail-closed or fail-in-place is chosen for the safest result for the process, not for convenience.", "## Characteristics", "The inherent characteristic describes how flow changes with opening. Linear valves give flow in proportion to position. Equal-percentage valves give small flow changes at low openings and large ones at high openings, which suits systems where pressure drop changes. Quick-opening valves suit on-off duty.", "## Problems", "Sticking, called stiction, makes the loop hunt. Oversized valves operate near closed and control poorly. Cavitation and flashing damage trim. Smart positioners report signature tests and diagnostics, which help to find problems before they cause a shutdown."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Control valves and positioners"}', 1, 20);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('instrument-calibration', 'Instrument calibration: why and how', 'Instrumentation', 5, 'Compare against a better standard, record as-found and as-left, and keep it traceable.', '{"body": ["Calibration compares an instrument with a more accurate reference and, where needed, adjusts it. Readings that drift can cause bad product, wasted energy and unsafe decisions without anyone noticing.", "## The basic method", "Apply known inputs, such as 0, 25, 50, 75 and 100 percent of range, first rising and then falling. Record what the instrument reports at each point. This is the as-found result. If errors are outside tolerance, adjust and repeat to record the as-left result.", "## Hysteresis and repeatability", "If the rising and falling readings differ, the instrument has hysteresis. If repeated runs disagree, it has poor repeatability. Both are worth recording because they show mechanical wear or a damaged sensor.", "## Standards and traceability", "The reference standard should be clearly more accurate than the device under test, commonly four times or better, and have a current calibration certificate traceable to national standards. Accredited laboratories work to ISO/IEC 17025.", "## Records and frequency", "Keep a certificate for each instrument with the date, standard used, results and technician. Choose intervals from the criticality of the measurement and its drift history. Calibrate the whole loop, not only the transmitter, to prove that the reading on the control room screen is true."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Instrument calibration: why and how"}', 1, 21);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('industrial-networks-profinet', 'Industrial networks: PROFIBUS, PROFINET and EtherNet/IP', 'Networks', 5, 'How controllers, drives and I/O talk to each other, and where to look when they stop.', '{"body": ["Modern plants replace thousands of individual wires with a few network cables. The main protocols differ in history and vendor, but share similar principles.", "## PROFIBUS", "PROFIBUS DP is a serial fieldbus using RS-485 wiring, with a bus topology. It must be terminated at both ends and uses shielded cable. It is widespread in older plants and is still supported by many drives and instruments.", "## PROFINET", "PROFINET runs on standard industrial Ethernet. Devices are identified by a unique name as well as an IP address, and it supports line, star and ring topologies. Real-time communication ensures that cyclic data arrives on time.", "## EtherNet/IP and Modbus", "EtherNet/IP is widely used with Rockwell and Allen-Bradley controllers. Modbus TCP is a simple, open protocol found on many meters and third-party devices.", "## Fault finding", "Begin with the physical layer: link lights, cable, connectors and power. Check for duplicate addresses and wrong device names. Look at the network topology in the engineering software, which shows which device lost contact first. Use industrial-grade switches, keep control networks separate from office networks, and document every IP address."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Industrial networks: PROFIBUS, PROFINET and EtherNet/IP"}', 1, 22);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('scada-hmi-and-alarms', 'SCADA, HMI and good alarm design', 'Automation', 5, 'Operators need clear screens and meaningful alarms, not more data.', '{"body": ["An HMI, human-machine interface, is the screen an operator uses at a machine. SCADA, supervisory control and data acquisition, collects data from many controllers across a site, stores it in a historian and shows it on operator stations.", "## Architecture", "Field instruments connect to PLCs. The PLCs send data to a SCADA server. Operator clients display screens, trends and alarms. A historian stores values so that engineers can analyse events and trends later.", "## Designing screens", "Show normal conditions in quiet colours and use bright colours only for abnormal states. Group information in the way operators think about the process. Include trends beside values, since a trend tells you where a number is heading. Keep navigation consistent from screen to screen.", "## Alarm management", "Alarm floods hide the one alarm that matters. Good practice, such as ISA-18.2 and IEC 62682, says that every alarm needs a clear operator action, a priority and a defined response. Review the most frequent alarms regularly and remove or fix the nuisance ones.", "## Security", "Industrial control systems are targets. Separate networks into zones, limit remote access, apply updates carefully and keep backups of every program. IEC 62443 provides a framework."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: SCADA, HMI and good alarm design"}', 1, 23);
INSERT OR IGNORE INTO articles (slug, title, cat, mins, sum, data, published, sort) VALUES ('maintenance-strategies', 'Preventive, predictive or reactive: choosing a maintenance strategy', 'Maintenance', 5, 'A good plant uses all three, in the right proportion, for the right equipment.', '{"body": ["Maintenance is a major cost, and unplanned downtime costs more. In mining and processing, an hour of lost production can far exceed the price of the part that failed.", "## Reactive", "Run to failure and repair when it breaks. This is acceptable for cheap, non-critical items with spares on hand. It is a poor choice for equipment that stops the plant or creates a safety risk.", "## Preventive", "Service at fixed intervals, regardless of condition: change oil, grease bearings, tighten terminations, test protection. It reduces failures, but can waste effort replacing parts that are still good.", "## Predictive", "Monitor the actual condition and act when it changes. Vibration analysis finds bearing and alignment problems. Thermography finds hot connections. Motor current and oil analysis reveal trouble early. The aim is to repair just before failure.", "## The failure curve", "Equipment often has early failures, a long period of random failures, and then wear-out. Strategy should reflect where each asset is on that curve and how critical it is.", "## Making it work", "Rank equipment by criticality, record every job in a maintenance system, and review failure history. A written plan with clear intervals, spares and responsibilities beats good intentions. Planned shutdowns are the best time for the jobs that cannot be done while running."], "img": "data:image/svg+xml;base64,", "alt": "Diagram: Preventive, predictive or reactive: choosing a maintenance strategy"}', 1, 24);
